using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.ComponentModel;
namespace V15Voice {
public sealed class VoiceProcessDiagnostic {
 public string Step,Process,Log,Exception,Disposition;public int? ExitCode,Unit,Stage;
}
public sealed partial class VoiceRenderReport {
 public string StepCode="INPUT",StepName="Kiểm tra đầu vào",FailureCode="",FailureDetail="";
 public string FailureStep="",FailureStepName="";public int? FailureUnit,FailureStage;
 public readonly List<VoiceProcessDiagnostic> ProcessDiagnostics=new List<VoiceProcessDiagnostic>();
 public void Step(string code,string label){lock(sync){if(StepCode!=code||StepName!=label){StepCode=code;StepName=label;Append("Bước "+code+": "+label);}}}
 public void ProcessFailure(string process,int? exitCode,string log,Exception error,bool retry){lock(sync){var d=new VoiceProcessDiagnostic{Step=StepCode,Process=process,ExitCode=exitCode,Log=log??"",Exception=error==null?"":ExceptionText(error),Disposition=retry?"Sẽ thử lại/dự phòng; chưa phải lỗi cuối":"Không thử lại trong bước này",Unit=Current==null?(int?)null:Current.Number,Stage=CurrentStage==null?(int?)null:CurrentStage.Number};ProcessDiagnostics.Add(d);Append("Chẩn đoán tiến trình "+process+"; exit="+(exitCode.HasValue?exitCode.ToString():"chưa có")+"; "+d.Disposition+"\r\n"+d.Exception+"\r\n"+d.Log);}}
 static string ExceptionText(Exception e){var b=new StringBuilder();int depth=0;for(var x=e;x!=null;x=x.InnerException){b.Append("Exception[").Append(depth++).Append("]: ").Append(x.GetType().FullName).Append("; HResult=0x").Append(x.HResult.ToString("X8")).AppendLine();var w=x as Win32Exception;if(w!=null)b.Append("Win32 native code: ").Append(w.NativeErrorCode).AppendLine();foreach(System.Collections.DictionaryEntry entry in x.Data)b.Append(entry.Key).Append(": ").Append(entry.Value).AppendLine();}b.Append(e.ToString());return b.ToString();}
 void CaptureFailure(Exception e){FailureStep=StepCode;FailureStepName=StepName;FailureUnit=Current==null?(int?)null:Current.Number;FailureStage=CurrentStage==null?(int?)null:CurrentStage.Number;FailureDetail=ExceptionText(e);FailureCode=e is OperationCanceledException?"CANCELLED":StepCode=="AI_REWRITE"?"AI_REWRITE_FAILED":StepCode=="FIT_RESULT"?"TIMELINE_MISMATCH":StepCode=="TTS"?"TTS_FAILED":StepCode=="FIT"?"TEMPO_PROCESS_FAILED":StepCode=="MODEL"?"MODEL_PREFLIGHT_FAILED":StepCode=="NORMALIZE"?"NORMALIZATION_FAILED":StepCode=="PUBLISH"?"WAV_PUBLISH_FAILED":StepCode=="ASSEMBLE"?"AUDIO_ASSEMBLY_FAILED":StepCode=="FORMAT"?"WAV_VALIDATION_FAILED":"INPUT_OR_SETUP_FAILED";}
 public void PlanStages(IEnumerable<AnchorStage> plan){lock(sync){foreach(var s in plan)if(!Stages.Any(x=>x.Number==s.Number))Stages.Add(new VoiceReportStage{Number=s.Number,Start=s.Start,End=s.End,Text=s.Text,CueIds=s.Cues.Select(c=>c.Id).ToList()});}}
 public void FitBudget(double source,double target){lock(sync){if(Current!=null){Current.WorkingBefore=source;Current.Target=target;Current.RequiredSpeed=target>0?options.BaseSpeed*source/target:(double?)null;}else if(CurrentStage!=null){CurrentStage.RequiredSpeed=target>0?options.BaseSpeed*source/target:(double?)null;}}}
 public void StageComponents(double tts,double innerPauses,double betweenPauses,double breaths,double measured){lock(sync){if(CurrentStage==null)return;CurrentStage.Tts=tts;CurrentStage.InnerPauses=innerPauses;CurrentStage.BetweenPauses=betweenPauses;CurrentStage.Breaths=breaths;CurrentStage.Before=measured;CurrentStage.RequiredSpeed=options.BaseSpeed*measured/(CurrentStage.End-CurrentStage.Start);Append("Chặng "+CurrentStage.Number+": TTS gốc="+F(tts)+"s; nghỉ trong đơn vị="+F(innerPauses)+"s; nghỉ giữa đơn vị="+F(betweenPauses)+"s; hơi thở="+F(breaths)+"s; tổng đo="+F(measured)+"s");}}
 void Diagnostics(Action<string> line){line("");line("CHẨN ĐOÁN QUY TRÌNH · mã app khác mã hệ điều hành/tiến trình");line("Bước cuối: "+StepCode+" · "+StepName);line("Mã kết quả app: "+(FailureCode.Length>0?FailureCode:Complete?"SUCCESS":"IN_PROGRESS"));if(FailureCode.Length>0){line("Bước phát sinh lỗi: "+FailureStep+" · "+FailureStepName);line("Đơn vị đang xử lý: "+(FailureUnit.HasValue?FailureUnit.ToString():"không có / chưa xác định")+"; chặng đang xử lý: "+(FailureStage.HasValue?FailureStage.ToString():"không có / xem các chặng không khớp"));line(FailureCode=="TIMELINE_MISMATCH"?"Đã có audio ứng viên nhưng không vừa timeline; xem số đo và lịch sử từng đơn vị/chặng lỗi.":FailureCode=="TTS_FAILED"?"Lỗi khi yêu cầu/đọc audio TTS. Không kết luận câu quá dài nếu chưa đo được âm thanh; kiểm tra lỗi gốc trước.":"Không tự kết luận phải sửa lời từ lỗi này; kiểm tra bước và thông báo gốc.");line("Ngoại lệ gốc, chuỗi nguyên nhân và mã do hệ thống cung cấp:");line(FailureDetail);}line("Trạng thái chặng: "+Stages.Count(s=>s.Status=="Đạt khung chặng")+" đạt; "+Stages.Count(s=>s.Status=="Không khớp khung chặng"||s.Status=="Lỗi tại chặng")+" lỗi; "+Stages.Count(s=>s.Status=="Đã dừng tại chặng")+" dừng; "+Stages.Count(s=>s.Status=="Chưa chạy tới")+" chưa chạy. Đạt chặng chưa có nghĩa đã xuất WAV cuối.");foreach(var d in ProcessDiagnostics){line("Tiến trình: "+d.Process+"; bước="+d.Step+"; đơn vị="+(d.Unit.HasValue?d.Unit.ToString():"chưa xác định")+"; chặng="+(d.Stage.HasValue?d.Stage.ToString():"chưa xác định")+"; exit="+(d.ExitCode.HasValue?d.ExitCode.ToString()+" / 0x"+d.ExitCode.Value.ToString("X8"):"chưa có mã thoát xác nhận"));line(d.Disposition);line(d.Exception);line("Đầu ra lỗi đã thu (bộ đệm có giới hạn; có thể chưa gồm dòng bất đồng bộ cuối):");line(d.Log);}}
 void Estimate(Action<string> line,double? required,double? target,List<VoiceReportAttempt> attempts){line("Đích căn thực tế: "+F(target)+"s; tốc độ ƯỚC TÍNH trước giới hạn: "+F(required)+"x"+(required.HasValue?"; "+Change(required.Value):""));line("Ước tính = tốc độ gốc × thời lượng đầu vào / đích căn; không phải kết quả đã thử hoặc cam kết sẽ vừa khung.");if(attempts.Count>0){var a=attempts.Last();line("Lần thử CUỐI đã đo: "+F(a.Speed)+"x; "+F(a.Measured)+"s; chênh đo-đích "+F(a.Measured-a.Target)+"s. Dương=dư, âm=thiếu. Kết quả được chọn có thể là lần thử khác.");}}
}
}
